import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.WFmvnizL.js";const m=JSON.parse('{"title":"Nezha Monitoring V2 - Open-source server monitoring and operations","titleTemplate":"Official Documentation","description":"Official Nezha Monitoring V2 documentation for self-hosted multi-server metrics, website and port checks, alerts, web terminal, files, tasks, DDNS, APIs, installation, configuration, and troubleshooting.","frontmatter":{"layout":"home","title":"Nezha Monitoring V2 - Open-source server monitoring and operations","titleTemplate":"Official Documentation","description":"Official Nezha Monitoring V2 documentation for self-hosted multi-server metrics, website and port checks, alerts, web terminal, files, tasks, DDNS, APIs, installation, configuration, and troubleshooting.","hero":{"name":"Nezha Monitoring V2","text":"Open-source, self-hosted server monitoring and operations","tagline":"Connect multiple Agents to one Dashboard to view server state, check websites and network services, send alerts, and perform authorized operations.","image":"https://raw.githubusercontent.com/nezhahq/nezha/master/.github/brand.svg","actions":[{"theme":"brand","text":"Preview","link":"https://qio.ng"},{"theme":"alt","text":"Install Dashboard →","link":"/en_US/guide/dashboard.html"}]},"features":[{"title":"Multi-server state","details":"View online state, CPU, memory, disk, network traffic, and available system metrics from Linux, Windows, macOS, OpenWRT, Synology, and other documented environments."},{"title":"Service checks and alerts","details":"Run HTTP GET, ICMP Ping, and TCPing from selected Agents, track availability, latency, and certificate state, and send alerts through notification groups."},{"title":"Routine remote operations","details":"Use web terminal, file management, scheduled and triggered tasks, DDNS, NAT, REST API, and optional MCP according to granted permissions."},{"title":"Self-hosted and open source","details":"Dashboard and Agent are published by NezhaHQ; the operator controls data, endpoints, users, storage, and integrations."}]},"headers":[],"relativePath":"en_US/index.md","filePath":"en_US/index.md","lastUpdated":1785844584000}'),r={name:"en_US/index.md"};function o(s,e,d,l,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="what-is-nezha-monitoring-v2" tabindex="-1">What is Nezha Monitoring V2? <a class="header-anchor" href="#what-is-nezha-monitoring-v2" aria-label="Permalink to &quot;What is Nezha Monitoring V2?&quot;">​</a></h2><p>Nezha Monitoring V2 combines a central <strong>Dashboard</strong> with an <strong>Agent</strong> installed on every monitored device. Agents report host state and perform assigned network checks or authorized tasks. Dashboard manages identity and access, visualization, service monitoring, alert notifications, APIs, and configuration.</p><ul><li><a href="/en_US/guide/overview.html">Product overview: capabilities, audience, and FAQs</a></li><li><a href="/en_US/guide/architecture.html">Architecture and data flow: Dashboard, Agent, storage, and connections</a></li><li><a href="/en_US/guide/version-compatibility.html">Version and compatibility: V2, component releases, and <code>/api/v1</code></a></li><li><a href="/en_US/guide/security.html">Security and privacy: production checklist</a></li></ul><h2 id="typical-use-cases" tabindex="-1">Typical use cases <a class="header-anchor" href="#typical-use-cases" aria-label="Permalink to &quot;Typical use cases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Nezha V2 entry point</th></tr></thead><tbody><tr><td>Multi-region VPS and cloud servers</td><td>Central online state, resources, traffic, groups, alerts, and authorized remote operations</td></tr><tr><td>Website and port availability</td><td>HTTP, Ping, TCP, latency, packet loss, HTTPS certificate state, and failure notifications</td></tr><tr><td>Home labs, NAS devices, and small teams</td><td>Self-hosted Dashboard, users, public or authenticated status views, tasks, and file operations</td></tr><tr><td>Internal automation and AI tools</td><td>Scoped API Tokens, REST API, and an MCP endpoint that is disabled by default</td></tr></tbody></table><p>If your primary goal is a public status page, second-by-second deep observability, the PromQL ecosystem, or enterprise network-device management, read the <a href="/en_US/guide/comparison.html">comparison with Uptime Kuma, Netdata, Prometheus/Grafana, and Zabbix</a>.</p><h2 id="start-in-five-steps" tabindex="-1">Start in five steps <a class="header-anchor" href="#start-in-five-steps" aria-label="Permalink to &quot;Start in five steps&quot;">​</a></h2><ol><li>Read <a href="/en_US/guide/architecture.html">Architecture and data flow</a> and prepare domains, ports, TLS, and backup storage.</li><li><a href="/en_US/guide/dashboard.html">Install Dashboard</a> and replace the default password immediately.</li><li><a href="/en_US/guide/agent.html">Install Agent</a>, then confirm the first server stays online and reports continuously.</li><li>Configure <a href="/en_US/guide/services.html">service monitoring</a> and <a href="/en_US/guide/notifications.html">notifications</a>.</li><li>Complete the <a href="/en_US/guide/security.html">security and privacy checklist</a> before adding more users, APIs, or remote operations.</li></ol><h2 id="official-resources" tabindex="-1">Official resources <a class="header-anchor" href="#official-resources" aria-label="Permalink to &quot;Official resources&quot;">​</a></h2><ul><li><a href="https://github.com/nezhahq/nezha" target="_blank" rel="noreferrer">Dashboard source and releases</a></li><li><a href="https://github.com/nezhahq/agent" target="_blank" rel="noreferrer">Agent source and releases</a></li><li><a href="https://github.com/nezhahq/nezhahq.github.io" target="_blank" rel="noreferrer">Documentation source and issues</a></li><li><a href="https://t.me/nezhamonitoring_global" target="_blank" rel="noreferrer">Telegram English community</a></li><li><a href="https://t.me/nezhanews" target="_blank" rel="noreferrer">Telegram Chinese announcement channel</a></li></ul><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h2><h3 id="which-operating-systems-can-nezha-monitoring-v2-monitor" tabindex="-1">Which operating systems can Nezha Monitoring V2 monitor? <a class="header-anchor" href="#which-operating-systems-can-nezha-monitoring-v2-monitor" aria-label="Permalink to &quot;Which operating systems can Nezha Monitoring V2 monitor?&quot;">​</a></h3><p>Official installation and documentation cover Linux, Windows, and macOS, with additional guidance for OpenWRT, Synology, and other environments. Available metrics depend on the operating system, permissions, hardware, and Agent configuration.</p><h3 id="must-dashboard-and-agent-use-the-same-version" tabindex="-1">Must Dashboard and Agent use the same version? <a class="header-anchor" href="#must-dashboard-and-agent-use-the-same-version" aria-label="Permalink to &quot;Must Dashboard and Agent use the same version?&quot;">​</a></h3><p>They are released independently and do not require identical version numbers. Read both release notes and validate on a small set of nodes before a broad upgrade. See <a href="/en_US/guide/version-compatibility.html">Version and compatibility</a>.</p><h3 id="can-nezha-v2-monitor-websites-and-ssl-certificates" tabindex="-1">Can Nezha V2 monitor websites and SSL certificates? <a class="header-anchor" href="#can-nezha-v2-monitor-websites-and-ssl-certificates" aria-label="Permalink to &quot;Can Nezha V2 monitor websites and SSL certificates?&quot;">​</a></h3><p>Yes. HTTP GET service monitoring checks URL availability, and HTTPS targets are also checked for certificate state. Ping and TCPing cover network reachability and ports.</p><h3 id="must-data-be-uploaded-to-a-third-party-cloud" tabindex="-1">Must data be uploaded to a third-party cloud? <a class="header-anchor" href="#must-data-be-uploaded-to-a-third-party-cloud" aria-label="Permalink to &quot;Must data be uploaded to a third-party cloud?&quot;">​</a></h3><p>No. Dashboard and Agent can be self-hosted. Requests go to an external service only when you enable an integration such as OAuth2, notifications, DDNS, or a CDN.</p><h3 id="why-do-current-api-routes-still-use-api-v1" tabindex="-1">Why do current API routes still use <code>/api/v1</code>? <a class="header-anchor" href="#why-do-current-api-routes-still-use-api-v1" aria-label="Permalink to &quot;Why do current API routes still use `/api/v1`?&quot;">​</a></h3><p>API route version and product generation are separate. The current product is V2 while the implemented REST API continues to use <code>/api/v1</code>. Do not change routes to <code>/api/v2</code> unless official code introduces them.</p>',21)])])}const p=a(r,[["render",o]]);export{m as __pageData,p as default};
